import React from 'react';
import '../styles/searchPage.css';

function Comic({ characters }) {
  // URL for the image that indicates a character image is not available
  const notAvailableImage = "http://i.annihil.us/u/prod/marvel/i/mg/b/40/image_not_available.jpg";

  // Ensure characters is an array before mapping over it
  if (!Array.isArray(characters)) {
    // Optionally, you can render a placeholder or nothing if characters is not an array
    return <div>No characters to display</div>;
  }

  return (
    <div className="comic-book-content">
      {characters.map((character) => {
        // Construct the full image URL for the current character
        const characterImageUrl = `${character.thumbnail.path}.${character.thumbnail.extension}`;

        // Check if the character's image URL is the "not available" image
        if (characterImageUrl === notAvailableImage) {
          // If it is, skip rendering this character by returning null
          return null;
        }

        // Render the character if the image URL is not the "not available" image
        return (
          <div key={character.id}>
            <h2>{character.name}</h2>
            <img src={characterImageUrl} alt={character.name} />
          </div>
        );
      })}
    </div>
  );
}

export default Comic;
